_logging_userlogsetting_js,\n\tappconsumos_qa_mb_rules_service_initialize_js : appconsumos_qa_mb_rules_service_initialize_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnautorizar_js : appconsumos_qa_mb_rules_set_visiblebtnautorizar_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnconfirmar_js : appconsumos_qa_mb_rules_set_visiblebtnconfirmar_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnnetear_js : appconsumos_qa_mb_rules_set_visiblebtnnetear_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnrevisar_js : appconsumos_qa_mb_rules_set_visiblebtnrevisar_js,\n\tappconsumos_qa_mb_rules_zbodega_ago_srv_errorarchive_checkforsyncerror_js : appconsumos_qa_mb_rules_zbodega_ago_srv_errorarchive_checkforsyncerror_js,\n\tappconsumos_qa_mb_services_app_consumos_qa_service : appconsumos_qa_mb_services_app_consumos_qa_service,\n\tappconsumos_qa_mb_services_zbodega_ago_srv_service : appconsumos_qa_mb_services_zbodega_ago_srv_service,\n\tappconsumos_qa_mb_styles_styles_css : appconsumos_qa_mb_styles_styles_css,\n\tappconsumos_qa_mb_styles_styles_less : appconsumos_qa_mb_styles_styles_less,\n\tappconsumos_qa_mb_styles_styles_light_css : appconsumos_qa_mb_styles_styles_light_css,\n\tappconsumos_qa_mb_styles_styles_light_json : appconsumos_qa_mb_styles_styles_light_json,\n\tappconsumos_qa_mb_styles_styles_light_nss : appconsumos_qa_mb_styles_styles_light_nss,\n\tapplication_app : application_app,\n\ttsconfig_json : tsconfig_json,\n\tversion_mdkbundlerversion : version_mdkbundlerversion\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Bool_Estado_Usuarios(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n        \n        if(estado == \"Activo\"){\n            return true\n        }\n        if(estado == \"Inactivo\"){\n            return false\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Color_Estado_Usuarios(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n        \n        if(estado == \"Activo\"){\n            return \"Green\"\n        }\n        if(estado == \"Inactivo\"){\n            return \"Red\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function Create_Almacenes(context) {\n\n    let lista_almacenes = context.evaluateTargetPath('#Page:Agregar_Almacenes/#Control:FormCellListPicker_Almacenes/#Value');\n    let tipo_almacen = context.evaluateTargetPath('#Page:Agregar_Almacenes/#Control:FormCellListPicker_Tipo/#Value');\n    let repetidos = \"\";\n    let errores = [];\n    let exitosos = [];\n\n    if (lista_almacenes.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar al menos un almacén de la lista para continuar.`\n            }\n        });\n    }\n\n    if (!tipo_almacen || tipo_almacen < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un tipo de almacen.`\n            }\n        });\n    }\n\n    let tipoalmacen_value = tipo_almacen[0].ReturnValue;\n\n    let promises = lista_almacenes.map((almacen, i) => {\n        let nuevo_almacen = almacen.BindingObject;\n\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=almacen eq '${nuevo_almacen.almacen}'`)\n            .then(result => {\n                if (result.length === 0) {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_AlmacenesApp.action\",\n                        \"Properties\": {\n                            \"Properties\": {\n                                \"sociedad\": nuevo_almacen.sociedad,\n                                \"almacen\": nuevo_almacen.almacen,\n                               \"centro\": nuevo_almacen.centro,\n                                \"almacen_desc\": nuevo_almacen.almacen_desc,\n                                \"tipo\": tipoalmacen_value,\n                            }\n                        }\n                    }).then(() => {\n                        exitosos.push(`${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc})`);\n                    }).catch(() => {\n                        errores.push(`${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc})`);\n                    });\n                }\n                repetidos += `${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc}), `;\n                return Promise.resolve();\n            }).catch(() => {\n                errores.push(`${nuevo_almacen.almacen} (${nuevo_almacen.almacen_desc})`);\n            });\n    });\n\n    Promise.allSettled(promises).then(() => {\n\n        // Primero mostramos repetidos (si existen)\n        let repetidosPromise = Promise.resolve();\n        if (repetidos.length > 0) {\n            repetidosPromise = context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Repetidos\",\n                    \"Message\": `Se encontraron almacenes ya creados: ${repetidos}`\n                }\n            });\n        }\n\n        // Después de mostrar repetidos mostramos los otros mensajes\n        repetidosPromise.then(() => {\n            let mensajePromise;\n\n            if (errores.length > 0 && exitosos.length === 0) {\n                // Si todo falló\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": `Falló la creación de los almacenes.`\n                    }\n                });\n            } else if (errores.length > 0 && exitosos.length > 0) {\n                // Algunos fallaron, otros no\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta parcial\",\n                        \"Message\": `Algunos almacenes fueron creados exitosamente.\\n\\nAlmacenes con error:\\n${errores.join('\\n')}`\n                    }\n                });\n            } else {\n                // Todo fue exitoso\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Creación exitosa\",\n                        \"Message\": `Los Almacenes fueron creados exitosamente`\n                    }\n                });\n            }\n\n            // Finalmente, después de mostrar el mensaje final, cerramos la ventana\n            mensajePromise.then(() => {\n                context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Administracion/Lista_Almacenes.page\"\n                });\n            });\n        });\n    });\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default async function Create_Usuarios(context) {\n    let lista_empleados = context.evaluateTargetPath('#Page:Agregar_Usuarios/#Control:ListaEmpleados/#Value');\n    let rol = context.evaluateTargetPath('#Page:Agregar_Usuarios/#Control:rol/#Value');\n    let isadmin = context.evaluateTargetPath('#Page:Agregar_Usuarios/#Control:isadmin/#Value');\n    let repetidos = \"\";\n    let errores = [];\n    let exitosos = [];\n\n    if (lista_empleados.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar al menos un empleado de la lista para continuar`\n            }\n        });\n    }\n\n    if (!rol || rol.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un rol para los usuarios`\n            }\n        });\n    }\n\n    let rol_value = rol[0].ReturnValue;\n    \n    let promises = lista_empleados.map((empleado, i) => {\n        let nuevo_empleado = empleado.BindingObject;\n\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${nuevo_empleado.ficha}'`)\n            .then(result => {\n                if (result.length === 0) {\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_EmpleadosApp.action\",\n                        \"Properties\": {\n                            \"Properties\": {\n                                \"ficha\": nuevo_empleado.ficha,\n                                \"nombre\": nuevo_empleado.nombre,\n                                \"correo\": nuevo_empleado.correo,\n                                \"rol\": rol_value,\n                                \"isAdmin\":isadmin,\n                                \"cargo\": nuevo_empleado.cargo,\n                                \"sociedad\": nuevo_empleado.sociedad\n                            }\n                        }\n                    }).then(() => {\n                        exitosos.push(`${nuevo_empleado.nombre} (${nuevo_empleado.ficha})`);\n                    }).catch(() => {\n                        errores.push(`${nuevo_empleado.nombre} (${nuevo_empleado.ficha})`);\n                    });\n                }\n                repetidos += `${nuevo_empleado.nombre} (${nuevo_empleado.ficha}), `;\n                return Promise.resolve();\n            }).catch(() => {\n                errores.push(`${nuevo_empleado.nombre} (${nuevo_empleado.ficha})`);\n            });\n    });\n\n    Promise.allSettled(promises).then(() => {\n\n        // Primero mostramos repetidos (si existen)\n        let repetidosPromise = Promise.resolve();\n        if (repetidos.length > 0) {\n            repetidosPromise = context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Repetidos\",\n                    \"Message\": `Se encontraron usuarios ya creados: ${repetidos}`\n                }\n            });\n        }\n\n        // Después de mostrar repetidos mostramos los otros mensajes\n        repetidosPromise.then(() => {\n            let mensajePromise;\n\n            if (errores.length > 0 && exitosos.length === 0) {\n                // Si todo falló\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Error\",\n                        \"Message\": `Falló la creación de los usuarios.`\n                    }\n                });\n            } else if (errores.length > 0 && exitosos.length > 0) {\n                // Algunos fallaron, otros no\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta parcial\",\n                        \"Message\": `Algunos usuarios fueron creados exitosamente.\\n\\nUsuarios con error:\\n${errores.join('\\n')}`\n                    }\n                });\n            } else {\n                // Todo fue exitoso\n                mensajePromise = context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Creación exitosa\",\n                        \"Message\": `Se finalizó el proceso de creación exitosamente`\n                    }\n                });\n            }\n\n            // Finalmente, después de mostrar el mensaje final, cerramos la ventana\n            mensajePromise.then(() => {\n                context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Administracion/Lista_Usuarios.page\"\n                });\n            });\n        });\n    });\n\n\n    //[0].ReturnValue\n    //(lista_empleados[0].BindingObject)\n    //alert(JSON.stringify(context.evaluateTargetPath(\"#Page:Agregar_Usuarios/#Control:ListaEmpleados/#Value/#Index:1/BindingObject/cargo\")))\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Administracion(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.isAdmin && info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Administracion/Inicio_Admin.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Switch_Estado(context) {\n    const pageProxy = context.getPageProxy();\n    var sw_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\").getControl(\"estado_edit\")\n    var estado_temp = context.getValue()\n\n    if(estado_temp){\n        sw_component.setHelperText('Activo')\n    }else{\n        sw_component.setHelperText('Inactivo')\n    }\n\n    //alert(sw_component.getType())\n    //alert(JSON.stringify(object))\n    //alert(JSON.stringify(context.binding))\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Estado(context) {\n    const pageProxy = context.getPageProxy();\n    var sw_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\").getControl(\"estado_edit\")\n    var estado_temp = sw_component.getValue()\n\n    if(estado_temp){\n        return 'Activo'\n    }else{\n        return 'Inactivo'\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Rol_Admin_List(context) {\n    try {\n        var object = context.binding\n        var rol = object.rol\n        var isadmin = object.isAdmin\n        \n        return isadmin ? rol + \" - Admin\" : rol;\n\n        \n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function AppUpdateFailure(clientAPI) {\n    let result = clientAPI.actionResults.AppUpdate.error.toString();\n    var message;\n    console.log(result);\n    if (result.startsWith('Error: Uncaught app extraction failure:')) {\n        result = 'Error: Uncaught app extraction failure:';\n    }\n    if (result.startsWith('Error: LCMS GET Version Response Error Response Status: 404 | Body: 404 Not Found: Requested route')) {\n        result = 'Application instance is not up or running';\n    }\n    if (result.startsWith('Error: LCMS GET Version Response Error Response Status: 404 | Body')) {\n        result = 'Service instance not found.';\n    }\n\n    switch (result) {\n        case 'Service instance not found.':\n            message = 'Mobile App Update feature is not assigned or not running for your application. Please add the Mobile App Update feature, deploy your application, and try again.';\n            break;\n        case 'Error: LCMS GET Version Response Error Response Status: 404 | Body: Failed to find a matched endpoint':\n            message = 'Mobile App Update feature is not assigned to your application. Please add the Mobile App Update feature, deploy your application, and try again.';\n            break;\n        case 'Error: LCMS GET Version Response failed: Error: Optional(OAuth2Error.tokenRejected: The newly acquired or refreshed token got rejected.)':\n            message = 'The Mobile App Update feature is not assigned to your application or there is no Application metadata deployed. Please check your application in Mobile Services and try again.';\n            break;\n        case 'Error: Uncaught app extraction failure:':\n            message = 'Error extracting metadata. Please redeploy and try again.';\n            break;\n        case 'Application instance is not up or running':\n            message = 'Communication failure. Verify that the BindMobileApplicationRoutesToME Application route is running in your BTP space cockpit.';\n            break;\n        default:\n            message = result;\n            break;\n    }\n    return clientAPI.getPageProxy().executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/Application/AppUpdateFailureMessage.action\",\n        \"Properties\": {\n            \"Duration\": 0,\n            \"Message\": message\n        }\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nfunction sleep(ms) {\n    return (new Promise(function(resolve, reject) {\n        setTimeout(function() {\n            resolve();\n        }, ms);\n    }));\n}\nexport default function AppUpdateSuccess(clientAPI) {\n    var message;\n    // Force a small pause to let the progress banner show in case there is no new version available\n    return sleep(500).then(function() {\n        let result = clientAPI.actionResults.AppUpdate.data;\n        console.log(result);\n\n        let versionNum = result.split(': ')[1];\n        if (result.startsWith('Current version is already up to date')) {\n            return clientAPI.getPageProxy().executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/Application/AppUpdateSuccessMessage.action\",\n                \"Properties\": {\n                    \"Message\": `Ya estás usando la última versión: ${versionNum}`,\n                    \"NumberOfLines\": 2\n                }\n            });\n        } else if (result === 'AppUpdate feature is not enabled or no new revision found.') {\n            message = 'No se encontraron metadatos de la aplicación. Implemente su aplicación y vuelva a intentarlo.';\n            return clientAPI.getPageProxy().executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/Application/AppUpdateSuccessMessage.action\",\n                \"Properties\": {\n                    \"Duration\": 5,\n                    \"Message\": message,\n                    \"NumberOfLines\": 2\n                }\n            });\n        }\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function ClientIsMultiUserMode(clientAPI) {\n    return clientAPI.isAppInMultiUserMode();\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function GetClientSupportVersions(clientAPI) {\n    let versionInfo = clientAPI.getVersionInfo();\n    let versionStr = '';\n    Object.keys(versionInfo).forEach(function(key, index) {\n        // key: the name of the object key\n        // index: the ordinal position of the key within the object\n        //console.log(`Key: ${key}   Index: ${index}`);\n        if (key != 'Application Version') {\n            versionStr += `${key}: ${versionInfo[key]}\\n`;\n        }\n    });\n    return versionStr;\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function GetClientVersion(clientAPI) {\n    let versionInfo = clientAPI.getVersionInfo();\n    if (versionInfo.hasOwnProperty('Application Version')) {\n        return versionInfo['Application Version'];\n    }\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function OnWillUpdate(clientAPI) {\n\n    return clientAPI.executeAction('/appconsumos_qa_mb/Actions/Application/OnWillUpdate.action').then((result) => {\n        if (result.data) {\n            let _app_consumos_qa = clientAPI.executeAction('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/CloseOffline.action');\n            let ZBODEGA_AGO_SRV = clientAPI.executeAction('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/CloseOffline.action');\n            return Promise.all([_app_consumos_qa, ZBODEGA_AGO_SRV]).then(() => {\n                Promise.resolve();\n            }).catch((err) => {\n                Promise.reject('Error al cerrar Odatas sin conexión ' + err.message);\n            });\n        } else {\n            return Promise.reject('User Deferred');\n        }\n    });\n\n\n}\n\n\n\n\n\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function ResetAppSettingsAndLogout(clientAPI) {\n    let logger = clientAPI.getLogger();\n    let platform = clientAPI.nativescript.platformModule;\n    let appSettings = clientAPI.nativescript.appSettingsModule;\n    var appId;\n    if (platform && (platform.isIOS || platform.isAndroid)) {\n        appId = clientAPI.evaluateTargetPath('#Application/#AppData/MobileServiceAppId');\n    } else {\n        appId = 'WindowsClient';\n    }\n    try {\n        // Remove any other app specific settings\n        appSettings.getAllKeys().forEach(key => {\n            if (key.substring(0, appId.length) === appId) {\n                appSettings.remove(key);\n            }\n        });\n    } catch (err) {\n        logger.log(`ERROR: AppSettings cleanup failure - ${err}`, 'ERROR');\n    } finally {\n        // Logout \n        return clientAPI.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/Application/Reset.action');\n    }\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Materiales_Solicitud(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Campo/#Control:material/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Campo/#Control:cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n    \n    let data = material[0].BindingObject\n    let stock = data.stock_disponible\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(stock == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `No hay stock disponible para este material`\n            }\n        });\n    }*/\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und`\n            }\n        });\n    }*/\n    \n    const duplicado = clientData.lista_materiales.filter(m => m.material === data.material && m.almacen.almacen === data.almacen.almacen).length > 0\n    \n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    clientData.lista_materiales.push(data)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Borrar_Material_Lista(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_materiales.findIndex(item => item.material === data.material && item.almacen.almacen === data.almacen.almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_materiales.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' del ${data.almacen.almacen_desc} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Estado_Sol_Campo(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n        \n        if(estado == \"Enviado\"){\n            return \"Grey\"\n        }\n        if(estado == \"Aprobado\"){\n            return \"Mango\"\n        }\n        if(estado == \"Rechazado\"){\n            return \"Red\"\n        }\n        if(estado == \"Autorizado\"){\n            return \"Green\"\n        }\n        if(estado == \"Tramitado\"){\n            return \"Teal\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","import guid from '../guid'\n\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Create_Componentes_Solicitud(context) {\n    let actionResult = context.getActionResult(\"Create_Solicitud_Campo\")\n    let data = JSON.parse(actionResult.data)\n    let idSolicitud = data.id\n\n \n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    let lista_materiales = clientData.lista_materiales;\n \n    // Obtener datos del almacén desde ClientData\n    let dataAlmacen = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject \n \n    let exitosos = [];\n    let errores = [];\n \n    // Create de la solicitud\n    let promises = lista_materiales.map(material => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_ComponentesSolicitudApp.action\",\n            \"Properties\": {\n                \"Properties\": {\n                    \"id\": guid(context),\n                    \"material_material\": material.material,\n                    \"material_almacen\": material.almacen.almacen,\n                    \"material_centro\": material.almacen.centro,\n                    \"material_sociedad\": material.almacen.sociedad,\n                    \"almacen_sociedad\": dataAlmacen.sociedad,\n                    \"almacen_almacen\": dataAlmacen.almacen,\n                    \"almacen_centro\": dataAlmacen.centro,\n                    \"solicitud_id\": idSolicitud,\n                    \"cantidad_tomada\": material.cant\n                }\n            }\n        }).then(() => {\n            exitosos.push(`${material.almacen.almacen_desc} - ${material.material_desc}`);\n        }).catch(() => {\n            errores.push(`${material.almacen.almacen_desc} - ${material.material_desc}`);\n        });\n    });\n \n    // Procesar los resultados\n    return Promise.allSettled(promises).then(() => {\n        let mensaje = '';\n \n        if (errores.length === 0) {\n            mensaje = 'Solicitud creada. Todos los materiales fueron agregados exitosamente a la solicitud.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud creada. Falló la creación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud creada. Algunos materiales fueron agregados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n \n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            // Finalmente cerrar el modal\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Campo/Detalle_Orden_Campo.page\"\n            });\n        });\n    });\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_Agregar_Solicitud_Campo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    clientData.lista_materiales = []\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Agregar_Solicitud_Campo.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_Campo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Filtro_Campo.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_List_Campo(context) {\n    let centro = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject.centro\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    clientData.centro = centro\n    clientData.lista_campo = []\n    \n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Lista_Ordenes_Campo.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_List_Sol_Campo(context) {\n    let data = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value')[0].BindingObject\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    \n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    clientData.centro = data.centro\n    clientData.almacen = data.almacen\n    clientData.sociedad = data.sociedad\n    clientData.lista_sol_campo = []\n\n    let filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'CAMPO' &$orderby=fecha_creacion desc`\n\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if(isTecnico){\n        let correo = clientDataUser.info_user.correo\n        //filtro += ` and correo_creacion eq ${correo}`\n        filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'CAMPO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc`\n    }\n\n    //+\"&$orderby=fecha_creacion desc\"\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'VerSolicitudesAbiertas', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_sol_campo = results\n           \n        }else{\n            clientData.lista_campo = []\n        }\n\n        context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Lista_Solicitudes_Campo.page\"\n            }\n        });\n    }).catch((error) => {\n        \n        alert(`Error ${error.message}`)\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_RevisionSolicitudCampo(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Campo').getClientData();\n    clientData.lista_mat_solicitud_campo = []\n    \n    \n \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Campo/Revision_Solicitud_Campo.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Campo(context) {\n    let id_solicitud = context.binding.id\n\n     let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Select_almacen(context) {\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Campo/#Control:almacen_campo/#Value');\n    const pageProxy = context.getPageProxy();\n    var btn_orden = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton0\")\n    var btn_solicitud = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton1\")\n    var btn_historico = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton2\")\n\n    if (almacen.length > 0) {\n        btn_orden.setEnabled(true)\n        btn_solicitud.setEnabled(true)\n        btn_historico.setEnabled(true)\n    }else{\n        btn_orden.setEnabled(false)\n        btn_solicitud.setEnabled(false)\n        btn_historico.setEnabled(false)\n    }\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Lista_Campo(context) {\n\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Campo/#ClientData/#Property:lista_campo\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.sociedad || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Lista_Materiales(context) {\n\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Orden_Campo/#ClientData/#Property:lista_materiales\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.material || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.material_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Solicitudes_Campo(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Campo/#ClientData/#Property:lista_sol_campo\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return prod.orden.toLowerCase().includes(lowerSearch) ||\n                prod.or_desc.toLowerCase().includes(lowerSearch) ||\n                prod.or_centro_plan.toLowerCase().includes(lowerSearch) ||\n                prod.or_grupo_plan.toLowerCase().includes(lowerSearch) ||\n                prod.equipo_solicitud.toLowerCase().includes(lowerSearch) ||\n                prod.eq_desc_solicitud.toLowerCase().includes(lowerSearch) ||\n                prod.reserva.toLowerCase().includes(lowerSearch) ||\n                prod.alm_sociedad.toLowerCase().includes(lowerSearch) ||\n                prod.estado.toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Validate_Req_Create_Solicitud_Campo(context) {\n    let clientDataDetalle = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Campo').getClientData();\n    clientDataDetalle.lista_materiales\n    let ficha = context.evaluateTargetPath('#Page:Agregar_Solicitud_Campo/#Control:ficha/#Value');\n    if(ficha){\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${ficha}'`).then(async (results) => {\n            if (results && results.length > 0) {\n                \n                if(clientDataDetalle.lista_materiales && clientDataDetalle.lista_materiales.length > 0 ){\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Confirmación\",\n                            \"Message\": `¿Estás seguro que quieres crear la solicitud?`,\n                            \"OKCaption\": \"Aceptar\",\n                            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Campo.action\",\n\t                        \"CancelCaption\": \"Cancelar\"\n                        }\n                    });\n                    //return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Campo.action\");\n                }\n\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta\",\n                        \"Message\": `Debes ingresar al menos un material a la solicitud para continuar`\n                    }\n                });\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n\n        }).catch((error) => {\n            \n            alert(`Error al encontrar la ficha ${error.message}`)\n        });\n\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `Debes ingresar el número de ficha para continuar`\n        }\n    });\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Date(context) {\n    var object = context.binding\n    var fecha = object.fecha_creacion\n    let fechaFormateada = `Fe. Creación: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_Date_ref(context) {\n    var object = context.binding\n    var fecha = object.fecha_referencia\n    let fechaFormateada = `Fe. Referencia: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_List_Campo_Equipo(context) {\n    const pageProxy = context.getPageProxy();\n    let equipos = context.evaluateTargetPath('#Page:Lista_Ordenes_Campo/#Control:filtro_equipos/#Value');\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Campo').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (equipos.length < 1) {\n        clientData.lista_campo = []\n        return list_component.redraw()\n    }\n\n    let filtro = '$filter='\n\n    equipos.forEach(e => {\n        filtro += `equipo eq '${e.BindingObject.equipo}' or `      \n    });\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Ordenes', [], filtro.slice(0, -4)+\"&$orderby=fecha_creacion desc\").then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_campo = results\n            list_component.redraw()\n        }else{\n            clientData.lista_campo = []\n            list_component.redraw()\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function isVisible_Btn_CrearSolicitudes(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    return info.rol === 'Técnico';\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function onChange_MaterialesRevision(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n\n    cantSolicitada.setVisible(false)\n    btn_aprobar.setVisible(true)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function setVisible_CantAprobadaRevision(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var label = cantSolicitada.getControl(\"FormCellLabel1\")\n    var cant_field = cantSolicitada.getControl(\"cantidad_revision\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Campo/#Control:materiales_solicitud/#Value');\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n    cantSolicitada.setVisible(true);\n\n    setTimeout(() => {\n        var cantSol = material[0].BindingObject.cantidad_tomada;\n        label.setText(`Cantidad Solicitada: ${cantSol}`);\n        cant_field.setValue(cantSol);\n        btn_aprobar.setVisible(false);\n    }, 200); // 200ms suele ser suficiente\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Aprobado_Solicitud(context) {\n    try {\n        var object = context.binding\n        var aprobado = object.aprobado\n       \n        if(aprobado == \"Aprobado\"){\n            return \"Green\"\n        }\n        if(aprobado == \"Rechazado\"){\n            return \"Red\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Material_Revision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    //clientData.lista_mat_solicitud_ing\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n    let cant = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellSimpleProperty_Cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    let data = material[0].BindingObject\n    let cantSolicitada = data.cantidad_tomada\n    let stock = data.stock_disponible\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n    if (cant > cantSolicitada) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `La cantidad aprobada (${cant}) es mayor a la solicitada (${cantSolicitada}).`\n            }\n        });\n    }\n\n    const duplicado = clientData.lista_mat_solicitud_ing.filter(m => m.mat_nuevo === data.mat_nuevo && m.almacen_almacen === data.almacen_almacen).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    data.aprobado = 'Aprobado'\n    clientData.lista_mat_solicitud_ing.push(data);\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material aprobado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n    \n    \n\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Materiales_Solicitud(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Ingenio/#Control:material/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Ingenio/#Control:cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n\n    let data = material[0].BindingObject\n    let stock = data.stock_disponible\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(stock == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `No hay stock disponible para este material`\n            }\n        });\n    }*/\n\n\n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad válida para continuar`\n            }\n        });\n    }\n\n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und`\n            }\n        });\n    }*/\n\n\n\n    /*var nuevo = {\n        id: data.almacen.almacen_desc+\"-\"+data.material,\n        material: data.material,\n        material_desc: data.material_desc,\n        almacen: data.almacen.almacen , \n        almacen_desc: data.almacen.almacen_desc,\n        centro: data.centro,\n        cant : cant,\n        stock_disponible: data.stock_disponible,\n        stock_reservado: data.stock_reservado\n    }*/\n\n    const duplicado = clientData.lista_materiales.filter(m => m.Matnr === data.Matnr && m.Lgort === data.Lgort).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n\n    data.cant = cant\n    clientData.lista_materiales.push(data)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Borrar_Material_Lista(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_materiales.findIndex(item => item.material === data.material && item.almacen.almacen === data.almacen.almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_materiales.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' del ${data.almacen.almacen_desc} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Borrar_Materiales_Revision_Ingenio(context) {\n    var data = context.binding\n    const pageProxy = context.getPageProxy();\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n\n    const index = clientData.lista_mat_solicitud_ing.findIndex(item => item.mat_nuevo === data.mat_nuevo && item.almacen_almacen === data.almacen_almacen);\n\n\n    if (index !== -1) {\n        clientData.lista_mat_solicitud_ing.splice(index, 1); // Elimina el elemento en esa posición\n\n    }\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.mat_nuevo_desc}' del ${data.almacen_almacen} eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    })\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Confirmar_ComponentesLista_Revision_Ingenio(context) {\n    \n}\n","import guid from '../guid'\n/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Create_Componentes_Solicitud_Ingenio(context) {\n\n    let actionResult = context.getActionResult(\"Create_Solicitud_Ingenio\")\n    let data = JSON.parse(actionResult.data)\n    let idSolicitud = data.id\n\n \n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    let lista_materiales = clientData.lista_materiales;\n\n    // Obtener datos del almacén desde ClientData\n    let dataAlmacen = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject \n \n    let exitosos = [];\n    let errores = [];\n\n    // Create de la solicitud\n        let promises = lista_materiales.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Create_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Properties\": {\n                        \"id\": guid(context),\n                        \"mat_nuevo\": material.Matnr,\n                        \"mat_nuevo_desc\": material.Txtmd,\n                        \"almacen_sociedad\": dataAlmacen.sociedad,\n                        \"almacen_almacen\": material.Lgort,\n                        \"almacen_centro\": material.Werks,\n                        \"solicitud_id\": idSolicitud,\n                        \"cantidad_tomada\": material.cant\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.Lgort} - ${material.Txtmd}`);\n            }).catch(() => {\n                errores.push(`${material.Lgort} - ${material.Txtmd}`);\n            });\n        });\n\n\n        // Procesar los resultados\n    return Promise.allSettled(promises).then(() => {\n        let mensaje = '';\n \n        if (errores.length === 0) {\n            mensaje = 'Solicitud creada. Todos los materiales fueron agregados exitosamente a la solicitud.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Solicitud creada. Falló la creación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Solicitud creada. Algunos materiales fueron agregados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n \n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            // Finalmente cerrar el modal\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Orden_Ingenio.page\"\n            });\n        });\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Filter_Materiales_Almacenes_Ingenio(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n \n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=tipo eq 'INGENIO'`).then(async (results) => {\n       \n        if (results && results.length > 0) {\n            let filtro = `$filter=Werks eq '${clientDataFiltro.centro_ingenio}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and (`\n \n            results.forEach(e => {\n                filtro += `Lgort eq '${e.almacen}' or `      \n            });\n \n            clientDataFiltro.filtroMaterial = filtro.slice(0, -4)+\")&$orderby=Matnr\"\n            //alert(clientDataFiltro.filtroMaterial)\n            //el centro esta indefinido\n            return clientDataFiltro.filtroMaterial;\n            \n \n        }\n        return null;\n    }).catch((error) => {\n       \n        alert(`Error al obtener los almacenes ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Agregar_Solicitud_Ingenio(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    clientData.lista_materiales = []\n    \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Agregar_Solicitud_Ingenio.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {xontext} clientAPI\n */\nexport default function NavTo_Ingenio(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Filtro_Ingenio.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function NavTo_List_Ingenio(context) {\n    let centro = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject.centro\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    clientData.centro_ingenio = centro\n    clientData.lista_ingenio = []\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Lista_Ordenes_Ingenio.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_List_Sol_Ingenio(context) {\n    let data = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value')[0].BindingObject\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    \n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    clientData.centro = data.centro\n    clientData.almacen = data.almacen\n    clientData.sociedad = data.sociedad\n    clientData.lista_sol_campo = []\n\n    let filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' &$orderby=fecha_creacion desc`\n\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if(isTecnico){\n        let correo = clientDataUser.info_user.correo\n        //filtro += ` and correo_creacion eq ${correo}`\n        filtro = `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc`\n    }\n\n    //+\"&$orderby=fecha_creacion desc\"\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'VerSolicitudesAbiertas', [], `$filter=alm_sociedad eq '${data.sociedad}' and alm_almacen eq '${data.almacen}' and alm_centro eq '${data.centro}' and tipo eq 'INGENIO' &$orderby=fecha_creacion desc`).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_sol_ingenio = results\n           \n        }else{\n            clientData.lista_sol_ingenio = []\n        }\n\n        context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Lista_Solicitudes_Ingenio.page\"\n            }\n        });\n    }).catch((error) => {\n        \n        alert(`Error ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_Revision_Solicitud_Ingenio(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    clientData.lista_mat_solicitud_ing = []\n    clientData.id_de_solicitud = context.binding.id;\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Ingenio/Revision_Solicitud_Ingenio.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Ingenio(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Materiales_Solicitud_Ingenio(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud}`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Rechazar_Material_Revision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Solicitudes_Ingenio').getClientData();\n    //clientData.lista_mat_solicitud_ing\n\n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n\n    let data = material[0].BindingObject\n\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n\n    const duplicado = clientData.lista_mat_solicitud_ing.filter(m => m.mat_nuevo === data.mat_nuevo && m.almacen_almacen === data.almacen_almacen).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Material no Agregado\",\n                \"Message\": `El material ya fue agregado anteriormente`\n            }\n        });\n    }\n\n    data.cant = 0\n    data.aprobado = 'Rechazado'\n    clientData.lista_mat_solicitud_ing.push(data);\n\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material Rechazado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n\n}\n","/**\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Solicitud(context) {\n    let id_solicitud = context.binding?.id;\n\n    if (!id_solicitud) {\n        alert(\"No se pudo obtener el ID de la solicitud para actualizar.\");\n        return Promise.resolve();\n    }\n\n    alert(`Actualizando solicitud ID: ${id_solicitud} a estado 'Rechazado'`);\n/* return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_SolicitudApp.action\",\n        \"Properties\": {\n            \"Target\": {\n                \"ReadLink\": context.binding[\"@odata.readLink\"]\n            },\n            \"Properties\": {\n                \"estado\": \"Rechazado\"\n            }\n        }\n    })\n        .then(() => {\n            alert(\"Solicitud actualizada a 'Rechazado' correctamente.\");\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"Properties\": {\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Solicitudes_Ingenio.page\"\n                }\n            });\n        })\n        .then(() => {\n            alert(\"Modal cerrado y navegación completada.\");\n        })\n        .catch((error) => {\n            alert(`Error al actualizar solicitud: ${error.message || 'Error desconocido'}`);\n        });*/\n    \n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Rechazar_Solicitud_Revision_Ingenio(context) {\n    alert(\"entró\")\n    let id_solicitud = context.binding.id;\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud}`;\n    let materialesRechazados = [];\n    let exitosos = [];\n    let errores = [];\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ComponentesSolicitud', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            for (let i = 0; i < results.length; i++) {\n                let item = results.getItem(i);\n                materialesRechazados.push({\n                    descripcion: item.mat_nuevo_desc,\n                    material: item.mat_nuevo,\n                    almacen_centro: item.almacen.centro,\n                    almacen_sociedad: item.almacen.sociedad,\n                    almacen_almacen: item.almacen.almacen,\n                    id_componente: item.id,\n                    readLink: item[\"@odata.readLink\"]\n                });\n            }\n        } else {\n            alert(\"No hay datos\");\n            return;\n        }\n\n        let promises = materialesRechazados.map(material => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/oData/Update_ComponentesSolicitudApp.action\",\n                \"Properties\": {\n                    \"Target\": {\n                        \"ReadLink\": material.readLink\n                    },\n                    \"Properties\": {\n                        \"id\": material.id_componente,\n                        \"cantidad_aprobada\": 0,\n                        \"aprobado\": false,\n                        \"confirmacion_tec\": false\n                    }\n                }\n            }).then(() => {\n                exitosos.push(`${material.material} - ${material.descripcion}`);\n            }).catch((error) => {\n                alert(`Error updating material ${material.material}:`, error);\n                errores.push(`${material.material} - ${material.descripcion}`);\n            });\n        });\n\n        // Procesar los resultados\n        return Promise.allSettled(promises).then(() => {\n            let mensaje = '';\n\n            if (errores.length === 0) {\n                mensaje = 'Solicitud Rechazada correctamente. Todos los materiales de la solicitud fueron rechazados exitosamente.';\n            } else if (exitosos.length === 0) {\n                mensaje = `Solicitud rechazada. Falló el rechazo de todos los materiales:\\n${errores.join('\\n')}`;\n            } else {\n                mensaje = `Solicitud rechazada parcialmente. Algunos materiales fueron rechazados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Resultado\",\n                    \"Message\": mensaje\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                    \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Ingenio/Detalle_Solicitudes_Ingenio.page\"\n                });\n            });\n        });\n\n    }).catch((error) => {\n        alert(`Error ${error.message}`);\n    });\n}","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function Select_Almacen_Ingenio(context) {\n    let almacen_ingenio = context.evaluateTargetPath('#Page:Filtro_Ingenio/#Control:FormCellListPicker_Almacen_O/#Value');\n    const pageProxy = context.getPageProxy();\n    var btn_orden = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton_Buscar\")\n    var btn_solicitud = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton1\")\n    var btn_historico = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton2\")\n    \n    if (almacen_ingenio.length > 0) {\n        btn_orden.setEnabled(true)\n        btn_solicitud.setEnabled(true)\n        btn_historico.setEnabled(true)\n    }else{\n        btn_orden.setEnabled(false)\n        btn_solicitud.setEnabled(false)\n        btn_historico.setEnabled(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Ingenio/#ClientData/#Property:lista_ingenio\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.orden_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.sociedad || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Materiales(context) {\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Orden_Ingenio/#ClientData/#Property:lista_materiales\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.Matnr || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.Txtmd || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Lista_Solicitudes_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Filtro_Ingenio/#ClientData/#Property:lista_sol_ingenio\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.orden || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.or_desc || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.or_centro_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.or_grupo_plan || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.equipo_solicitud || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.eq_desc_solicitud || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.reserva || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.alm_sociedad || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.estado || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Target_Materiales_Revision_Ingenio(context) {\n    let target = context.evaluateTargetPath(\"#Page:Detalle_Solicitudes_Ingenio/#ClientData/#Property:lista_mat_solicitud_ing\");\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.mat_nuevo || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.mat_nuevo_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Validate_Req_Create_Solicitud_Ingenio(context) {\n    let clientDataDetalle = context.evaluateTargetPathForAPI('#Page:Detalle_Orden_Ingenio').getClientData();\n    clientDataDetalle.lista_materiales\n    let ficha = context.evaluateTargetPath('#Page:Agregar_Solicitud_Ingenio/#Control:ficha/#Value');\n    if(ficha){\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${ficha}'`).then(async (results) => {\n            if (results && results.length > 0) {\n                \n                if(clientDataDetalle.lista_materiales && clientDataDetalle.lista_materiales.length > 0 ){\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Confirmación\",\n                            \"Message\": `¿Estás seguro que quieres crear la solicitud?`,\n                            \"OKCaption\": \"Aceptar\",\n                            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Ingenio.action\",\n\t                        \"CancelCaption\": \"Cancelar\"\n                        }\n                    });\n                    //return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Ingenio.action\");\n                }\n\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta\",\n                        \"Message\": `Debes ingresar al menos un material a la solicitud para continuar`\n                    }\n                });\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n\n        }).catch((error) => {\n            \n            alert(`Error al encontrar la ficha ${error.message}`)\n        });\n\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `Debes ingresar el número de ficha para continuar`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Date_creacion(context) {\n    var object = context.binding\n    var fecha = object.fecha_creacion\n    let fechaFormateada = `Fe. Creación: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Date_ref(context) {\n    var object = context.binding\n    var fecha = object.fecha_referencia\n    let fechaFormateada = `Fe. Referencia: $(D,${fecha.slice(0,4)}-${fecha.slice(4,6)}-${fecha.slice(6,8)})`;\n    return fechaFormateada\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_List_Ingenio_Equipo(context) {\n    const pageProxy = context.getPageProxy();\n    let equipos = context.evaluateTargetPath('#Page:Lista_Ordenes_Ingenio/#Control:FormCellListPicker_Equipos_Ord/#Value');\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Ingenio').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n\n    if (equipos.length < 1) {\n        clientData.lista_ingenio = []\n        return list_component.redraw()\n    }\n\n    let filtro = '$filter='\n\n    equipos.forEach(e => {\n        filtro += `equipo eq '${e.BindingObject.equipo}' or `      \n    });\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'Ordenes', [], filtro.slice(0, -4)+\"&$orderby=fecha_creacion desc\").then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.lista_ingenio = results\n            list_component.redraw()\n        }else{\n            clientData.lista_ingenio = []\n            list_component.redraw()\n        }\n    })\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function isVisible_Btn_CrearSolicitudes(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    return info.rol === 'Técnico';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function onChange_Materiales_Revision_Ing(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n \n    cantSolicitada.setVisible(false)\n    btn_aprobar.setVisible(true)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function setVisible_CantAprobadaRevision_Ingenio(context) {\n    const pageProxy = context.getPageProxy();\n    var cantSolicitada = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    var label = cantSolicitada.getControl(\"FormCellLabel1\")\n    var cant_field = cantSolicitada.getControl(\"FormCellSimpleProperty_Cantidad\")\n    var btn_aprobar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n \n    let material = context.evaluateTargetPath('#Page:Revision_Solicitud_Ingenio/#Control:FormCellListPicker_Materiales/#Value');\n \n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n    cantSolicitada.setVisible(true);\n \n    setTimeout(() => {\n        var cantSol = material[0].BindingObject.cantidad_tomada;\n        label.setText(`Cantidad Solicitada: ${cantSol}`);\n        cant_field.setValue(cantSol);\n        btn_aprobar.setVisible(false);\n    }, 200);\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Materiales_Nuevos_Reabas(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellListPicker_Materiales_Nuevo/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellSimpleProperty_Cantidad_Nuevo/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n\n    let data = material[0]    \n \n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad valida para continuar`\n            }\n        });\n    }\n  \n    var nuevo = {\n        material: data.ReturnValue,\n        material_desc: data.DisplayValue.Subhead,\n        cant : cant,\n        stock_disponible: null,\n        stock_reservado: null,\n        tipo: \"Nuevo\"\n    }\n   \n    const duplicado = clientData.lista_materiales.filter(m => m.material === nuevo.material).length > 0\n   \n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n \n    clientData.lista_materiales.push(nuevo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Materiales_Solicitud_Reabas(context) {\n\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n\n    let material = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellListPicker_Materiales/#Value');\n    let cant = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellSimpleProperty_Cantidad/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n    if (material.length < 1) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes seleccionar un material para continuar`\n            }\n        });\n    }\n   \n    let data = material[0].BindingObject\n    let stock = data.stock_disponible\n \n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(stock == 0){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `No hay stock disponible para este material`\n            }\n        });\n    }*/\n \n    if (!cant || cant < 0) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad valida para continuar`\n            }\n        });\n    }\n \n    //TODO DESCOMENTAR CUANDO HAYA INVENTARIO\n    /*if(cant > stock){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar una cantidad menor para continuar. La cantidad disponible es de ${stock} und`\n            }\n        });\n    }*/\n \n   \n \n    var nuevo = {\n        material: data.material,\n        material_desc: data.material_desc,\n        cant : cant,\n        stock_disponible: data.stock_disponible,\n        stock_reservado: data.stock_reservado,\n        tipo: \"Registrado\"\n    }\n \n   \n    const duplicado = clientData.lista_materiales.filter(m => m.material === data.material).length > 0\n   \n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `El material ya fue ingresado anteriormente`\n            }\n        });\n    }\n \n    clientData.lista_materiales.push(nuevo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Nuevo material agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n\n\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Borrar_Material_Lista_Abaste(context) {\n    const pageProxy = context.getPageProxy();\n    var data = context.binding\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\")\n   \n    const index = clientData.lista_materiales.findIndex(item => item.material === data.material);\n    if (index !== -1) {\n        clientData.lista_materiales.splice(index, 1); // Elimina el elemento en esa posición\n    }\n \n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Material '${data.material_desc}' eliminado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Estado_Abast(context) {\n    try {\n        var object = context.binding\n        var estado = object.estado\n       \n        if(estado == \"Enviado\"){\n            return \"Grey\"\n        }\n        if(estado == \"Aprobado\"){\n            return \"Mango\"\n        }\n        if(estado == \"Rechazado\"){\n            return \"Red\"\n        }\n        if(estado == \"Autorizado\"){\n            return \"Green\"\n        }\n        if(estado == \"Tramitado\"){\n            return \"Teal\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el valor:\", error);\n        alert(\"No se pudo obtener el valor: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Color_Tipo_ListaMaterial(context) {\n    try {\n        var object = context.binding\n        var tipo = object.tipo\n        \n        if(tipo == \"Registrado\"){\n            return \"Grey\"\n        }\n        if(tipo == \"Nuevo\"){\n            return \"Indigo\"\n        }\n    } catch (error) {\n        console.error(\"Ocurrió un error al obtener el color del tipo:\", error);\n        alert(\"No se pudo obtener el color del tipo: \" + error.message);\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nimport guid from '../guid'\nexport default function Create_Solicitud_Abastecimiento(context) {\n\n    let actionResult = context.getActionResult(\"Create_SolicitudApp_Abastecimiento\");\n\n    let data = JSON.parse(actionResult.data)\n    let idSolicitud = data.id\n\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    let lista_materiales = clientData.lista_materiales;\n\n    // Obtener datos del almacén desde ClientData\n    let clientDataAlmacen = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    let dataAlmacen = clientDataAlmacen.almacen_abast;\n\n\n    let exitosos = [];\n    let errores = [];\n\n    // Create de la solicitud\n    let promises = lista_materiales.map(material => {\n        let props = {\n            id: guid(context),\n            solicitud_id: idSolicitud,\n            cantidad_tomada: material.cant\n        };\n    \n        if (material.tipo === \"Nuevo\") {\n            props.mat_nuevo = material.material;\n            props.mat_nuevo_desc = material.material_desc;\n        } else if (material.tipo === \"Registrado\") {\n            Object.assign(props, {\n                material_material: material.material,\n                material_almacen: dataAlmacen.almacen,\n                material_centro: dataAlmacen.centro,\n                material_sociedad: dataAlmacen.sociedad,\n                almacen_sociedad: dataAlmacen.sociedad,\n                almacen_almacen: dataAlmacen.almacen,\n                almacen_centro: dataAlmacen.centro\n            });\n        }\n    \n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/oData/Create_ComponentesSolicitudApp.action\",\n            Properties: {\n                Properties: props\n            }\n        }).then(() => {\n            exitosos.push(`${material.material} (${material.material_desc})`);\n        }).catch(() => {\n            errores.push(`${material.material} (${material.material_desc})`);\n        });\n    });\n   \n    // Procesar los resultados\n    return Promise.allSettled(promises).then(() => {\n        let mensaje = '';\n\n        if (errores.length === 0) {\n            mensaje = 'Todos los materiales fueron agregados exitosamente a la solicitud.';\n        } else if (exitosos.length === 0) {\n            mensaje = `Falló la creación de todos los materiales:\\n${errores.join('\\n')}`;\n        } else {\n            mensaje = `Algunos materiales fueron agregados con éxito.\\n\\nErrores:\\n${errores.join('\\n')}`;\n        }\n\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Resultado\",\n                \"Message\": mensaje\n            }\n        }).then(() => {\n            // Finalmente cerrar el modal\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/CloseModalPage_Complete.action\",\n                \"NavigateBackToPage\": \"/appconsumos_qa_mb/Pages/Inventario/Lista_Solicitudes_Reabastecimiento.page\"\n            });\n        });\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Get_FilterRead_ZBIW_MARDT(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    return clientDataFiltro.filtroMaterial\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Get_List_Materiales_Nuevos(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    let materiales = clientDataFiltro.materiales_nuevos\n    return materiales\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Agregar_Solicitud_Reabastecimiento(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    //let materialesNuevos = clientDataFiltro.materiales_nuevos\n    clientData.lista_materiales = []\n\n    /*if(!materialesNuevos){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Cargando materiales, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }*/\n \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Agregar_Solicitud_Reabastecimiento.page\",\n            \"ModalPage\": true,\n            \"ModalPageFullscreen\": true\n        }\n    });\n \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Filtro_Abast(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Inicio_Inventario').getClientData();\n    clientData.lista_abast = []\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Filtro_Almacen_Solicitud_Abast.page\"\n        }\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function NavTo_Inventario(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user\n\n    if(!clientData.info_user){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Sincronizando datos, por favor espera un momento...`,\n                \"Duration\": 1\n            }\n        });\n    }\n\n    if (info.estado == 'Activo') {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n            \"Properties\": {\n                \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Inicio_Inventario.page\"\n            }\n        });\n    }\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `No tienes permisos para ingresar a este módulo`\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function NavTo_List_Abastecimiento(context) {\n    let almacen = context.evaluateTargetPath('#Page:Filtro_Almacen_Solicitud_Abast/#Control:FormCellListPicker_Almacen_Reabast/#Value')[0].BindingObject;\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    clientData.almacen_abast = almacen;\n    //alert(JSON.stringify(clientData.almacen_abast))\n    clientData.materiales_nuevos = []\n\n    let filtro = `$filter=Werks eq '${almacen.centro}' and Spras eq 'ES' and Lgort ne '${almacen.almacen}' and contains(Txtmd, 'BORRADO') eq false&$orderby=Lgort`\n\n    /*context.read('/appconsumos_qa_mb/Services/ZBODEGA_AGO_SRV.service', 'ZBIW_MARDTSet', [], filtro).then(async (results) => {\n\n        clientData.materiales_nuevos = []\n        context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": `Los materiales ya están disponibles. Puedes crear nuevas solicitudes.`,\n                \"Duration\": 1\n            }\n        });\n\n        if (results && results.length > 0) {\n            const materialesUnicos = results.filter(\n                (item, index, self) =>\n                    index === self.findIndex(m => m.Matnr === item.Matnr)\n            );\n\n            clientData.materiales_nuevos = materialesUnicos\n            \n        }\n    }).catch((error) => {\n\n        alert(`Error al obtener los materiales del ERP ${error.message}`)\n    });*/\n\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericNavigation.action\",\n        \"Properties\": {\n            \"PageToOpen\": \"/appconsumos_qa_mb/Pages/Inventario/Lista_Solicitudes_Reabastecimiento.page\"\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Abast(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=material,almacen&$filter=solicitud_id eq ${id_solicitud} and material_material ne null`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Detalle_Componentes_Abast_Nuevo(context) {\n    let id_solicitud = context.binding.id\n\n    let filtro = `$expand=almacen&$filter=solicitud_id eq ${id_solicitud} and mat_nuevo ne null`\n\n    return filtro\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Query_Lista_Abast(context) {\n    //let clientData = context.evaluateTargetPathForAPI('#Page:Inicio_Inventario').getClientData();\n    let clientDataUser = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let clientDataAlmacen = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n\n    let dataAlmacen = clientDataAlmacen.almacen_abast;\n\n    let filtro = `$filter=almacen_sociedad eq '${dataAlmacen.sociedad}' and almacen_almacen eq '${dataAlmacen.almacen}' and almacen_centro eq '${dataAlmacen.centro}' and tipo eq 'ABASTECIMIENTO' &$orderby=fecha_creacion desc &$expand=operario,aprobador,autorizador,almacen`\n    let isTecnico = clientDataUser.info_user.rol === 'Técnico'\n    if(isTecnico){\n        let correo = clientDataUser.info_user.correo\n        filtro = `$filter=almacen_sociedad eq '${dataAlmacen.sociedad}' and almacen_almacen eq '${dataAlmacen.almacen}' and almacen_centro eq '${dataAlmacen.centro}' and tipo eq 'ABASTECIMIENTO' and correo_creacion eq '${correo}' &$orderby=fecha_creacion desc &$expand=operario,aprobador,autorizador,almacen`\n    }\n    return filtro;\n    //lista_abast\n}\n","/**\n * Describe this function...\n * @param {context} clientAPI\n */\nexport default function Select_Almacen_Sol_Abast(context) {\n    let almacenLP = context.evaluateTargetPath('#Page:Filtro_Almacen_Solicitud_Abast/#Control:FormCellListPicker_Almacen_Reabast/#Value')\n    const pageProxy = context.getPageProxy();\n    var btn_crearSolicitud = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\").getControl(\"FormCellButton_Solicitudes\")\n\n    if (almacenLP.length > 0) {\n        btn_crearSolicitud.setEnabled(true)\n    }else{\n        btn_crearSolicitud.setEnabled(false)\n    }\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Target_Lista_Materiales_Agregados(context) {\n    let target = context.evaluateTargetPath('#Page:Lista_Solicitudes_Reabastecimiento/#ClientData/#Property:lista_materiales');\n    let searchString = context.searchString;\n\n    if (searchString) {\n        let lowerSearch = searchString.toLowerCase();\n\n        let searchResult = target.filter(prod => {\n            return (prod.material || \"\").toLowerCase().includes(lowerSearch) ||\n                (prod.material_desc || \"\").toLowerCase().includes(lowerSearch);\n        });\n\n        target = searchResult;\n    }\n\n    return target;\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Validate_Create_Solicitud_Abast(context) {\n    let clientDataDetalle = context.evaluateTargetPathForAPI('#Page:Lista_Solicitudes_Reabastecimiento').getClientData();\n    clientDataDetalle.lista_materiales\n    let ficha = context.evaluateTargetPath('#Page:Agregar_Solicitud_Reabastecimiento/#Control:FormCellSimpleProperty_Ficha/#Value');\n    if(ficha){\n        return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${ficha}'`).then(async (results) => {\n            if (results && results.length > 0) {\n                if(clientDataDetalle.lista_materiales && clientDataDetalle.lista_materiales.length > 0 ){\n                    return context.executeAction({\n                        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                        \"Properties\": {\n                            \"Title\": \"Confirmación\",\n                            \"Message\": `¿Estás seguro que quieres crear la solicitud?`,\n                            \"OKCaption\": \"Aceptar\",\n                            \"OnOK\": \"/appconsumos_qa_mb/Actions/oData/Create_SolicitudApp_Abastecimiento.action\",\n                            \"CancelCaption\": \"Cancelar\"\n                        }\n                    });\n                    //return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Create_Solicitud_Campo.action\");\n                }\n \n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Alerta\",\n                        \"Message\": `Debes ingresar al menos un material a la solicitud para continuar`\n                    }\n                });\n            }\n \n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n \n        }).catch((error) => {\n           \n            alert(`Error al encontrar la ficha ${error.message}`)\n        });\n \n    }\n \n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n        \"Properties\": {\n            \"Title\": \"Alerta\",\n            \"Message\": `Debes ingresar el número de ficha para continuar`\n        }\n    });\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function filter_Read_ZBIW_MARDT(context) {\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'AlmacenesApp', [], `$filter=sociedad eq '${clientDataFiltro.almacen_abast.sociedad}' and almacen ne '${clientDataFiltro.almacen_abast.almacen}'`).then(async (results) => {\n        \n        if (results && results.length > 0) {\n            let filtro = `$filter=Werks eq '${clientDataFiltro.almacen_abast.centro}' and Spras eq 'ES' and contains(Txtmd, 'BORRADO') eq false and contains(Txtmd, 'BORRAR') eq false and contains(Txtmd, 'BORRAD_') eq false and (`\n\n            results.forEach(e => {\n                filtro += `Lgort eq '${e.almacen}' or `      \n            });\n\n            clientDataFiltro.filtroMaterial = filtro.slice(0, -4)+\")&$orderby=Matnr\"\n            return context.executeAction(\"/appconsumos_qa_mb/Actions/oData/Read_ZBIW_MARDTSet.action\");\n\n        } \n    }).catch((error) => {\n        \n        alert(`Error al obtener los almacenes ${error.message}`)\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function set_VisibleAgregarMaterialExistente(context) {\n    const pageProxy = context.getPageProxy();\n    var agregarMaterialExistente = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var agregarMaterialNuevo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n    agregarMaterialExistente.setVisible(true)\n    agregarMaterialNuevo.setVisible(false)\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function set_VisibleAgregarMaterialNuevo(context) {\n\n    let clientDataFiltro = context.evaluateTargetPathForAPI('#Page:Filtro_Almacen_Solicitud_Abast').getClientData();\n    const pageProxy = context.getPageProxy();\n    var agregarMaterialExistente = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell1\")\n    var agregarMaterialNuevo = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell2\")\n\n    agregarMaterialExistente.setVisible(false)\n    agregarMaterialNuevo.setVisible(true)\n    agregarMaterialNuevo.redraw(true)\n\n    let actionResult = context.getActionResult(\"Read_ZBIW_MARDTSet\");\n    let string = JSON.stringify(actionResult.data)\n    //alert(JSON.stringify(JSON.parse(string)[0]))\n\n    let lista = JSON.parse(string)\n\n    const resultadoListPicker = [];\n    const vistos = new Set();\n\n    for (const item of lista) {\n        if (!vistos.has(item.Matnr)) {\n            vistos.add(item.Matnr);\n            resultadoListPicker.push({\n                ObjectCell: {\n                    Title: item.Matnr,\n                    Subhead: item.Txtmd,\n                    PreserveIconStackSpacing: false,\n                    Visible: true\n                },\n                ReturnValue: item.Matnr\n            });\n        }\n    }\n\n    clientDataFiltro.materiales_nuevos = resultadoListPicker\n\n}\n","export default function LogLevels(clientAPI) {\n    var levels = [];\n    levels.push({\n        'DisplayValue': 'Error',\n        'ReturnValue': 'Error',\n    });\n    levels.push({\n        'DisplayValue': 'Warning',\n        'ReturnValue': 'Warn',\n    });\n    levels.push({\n        'DisplayValue': 'Info',\n        'ReturnValue': 'Info',\n    });\n    levels.push({\n        'DisplayValue': 'Debug',\n        'ReturnValue': 'Debug',\n    });\n    levels.push({\n        'DisplayValue': 'Trace',\n        'ReturnValue': 'Trace',\n    });\n    return levels;\n}","export default function SetTraceCategories(clientAPI) {\n    var logger = clientAPI.getLogger();\n    const sectionedTable = clientAPI.getPageProxy().getControl('SectionedTable');\n    const fcsection = sectionedTable.getSection('FormCellSection0');\n    const traceCategory = fcsection.getControl('TracingCategoriesListPicker');\n    const odataTrace = fcsection.getControl('odataTrace');\n\n    try {\n        if (traceCategory.getValue()) {\n            var values = traceCategory.getValue();\n            var categories = [];\n\n            if (values && values.length) {\n                categories = values.map((value) => {\n                    return 'mdk.trace.' + value.ReturnValue;\n                });\n            }\n            clientAPI.setDebugSettings(odataTrace.getValue(), true, categories);\n        }\n    } catch (exception) {\n        logger.log(String(exception), 'Error');\n        return undefined;\n    }\n}","export default function SetUserLogLevel(clientAPI) {\n    try {\n        if (clientAPI.getValue() && clientAPI.getValue()[0]) {\n            var logger = clientAPI.getLogger();\n            var listPickerValue = clientAPI.getValue()[0].ReturnValue;\n            if (listPickerValue) {\n                switch (listPickerValue) {\n                    case 'Debug':\n                        logger.setLevel('Debug');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Error':\n                        logger.setLevel('Error');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Warn':\n                        logger.setLevel('Warn');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Info':\n                        logger.setLevel('Info');\n                        ShowTraceOptions(clientAPI, false);\n                        break;\n                    case 'Trace':\n                        logger.setLevel('Trace');\n                        ShowTraceOptions(clientAPI, true);\n                        break;\n                    default:\n                        // eslint-disable-next-line no-console\n                        console.log(`unrecognized key ${listPickerValue}`);\n                }\n                return listPickerValue;\n            }\n        }\n    } catch (exception) {\n        logger.log(String(exception), 'Error');\n        return undefined;\n    }\n}\n\nfunction ShowTraceOptions(clientAPI, tracingEnabled) {\n    let categories = clientAPI.getPageProxy().getControl('SectionedTable').getControl('TracingCategoriesListPicker');\n    let odataTrace = clientAPI.getPageProxy().getControl('SectionedTable').getControl('odataTrace');\n\n    categories.setVisible(tracingEnabled);\n    odataTrace.setVisible(tracingEnabled);\n}","export default function ToggleLogging(clientAPI) {\n    try {\n        var logger = clientAPI.getLogger();\n        const sectionedTable = clientAPI.getPageProxy().getControl('SectionedTable');\n        const fcsection = sectionedTable.getSection('FormCellSection0');\n        const enableLogSwitch = fcsection.getControl('EnableLogSwitch');\n        const logLevelListPicker = fcsection.getControl('LogLevelListPicker');\n        let switchValue = enableLogSwitch.getValue();\n        if (switchValue) {\n            logger.on();\n            logLevelListPicker.setVisible(true);\n            logLevelListPicker.setEditable(true);\n            logLevelListPicker.redraw();\n        } else {\n            logger.off();\n            logLevelListPicker.setEditable(false);\n            logLevelListPicker.setVisible(false);\n            logLevelListPicker.redraw();\n        }\n        return switchValue;\n    } catch (exception) {\n        logger.log(String(exception), 'Error');\n        return undefined;\n    }\n}","export default function TraceCategories(clientAPI) {\n    var categories = ['action', 'api', 'app', 'binding', 'branding',\n        'core', 'i18n', 'lcms', 'logging', 'odata', 'onboarding', 'profiling', 'push',\n        'restservice', 'settings', 'targetpath', 'ui'\n    ];\n\n    var values = [];\n    categories.forEach((category) => {\n        values.push({\n            'DisplayValue': category,\n            'ReturnValue': category,\n        });\n    });\n\n    return values;\n}","export default function UserLogSetting(clientAPI) {\n\n    try {\n        var logger = clientAPI.getLogger();\n\n        const sectionedTable = clientAPI.getControl('SectionedTable');\n        const fcsection = sectionedTable.getSection('FormCellSection0');\n        const enableLogSwitch = fcsection.getControl('EnableLogSwitch');\n        const logLevelListPicker = fcsection.getControl('LogLevelListPicker');\n        const traceCategory = fcsection.getControl('TracingCategoriesListPicker');\n        const odataTrace = fcsection.getControl('odataTrace');\n\n\n        //Persist the user logging preferences\n        if (logger) {\n            console.log(\"in logger state\");\n            if (logger.isTurnedOn()) {\n                if (enableLogSwitch) {\n                    enableLogSwitch.setValue(true);\n                }\n                if (logLevelListPicker) {\n                    logLevelListPicker.setEditable(true);\n                }\n            } else {\n                if (enableLogSwitch) {\n                    enableLogSwitch.setValue(false);\n                }\n                if (logLevelListPicker) {\n                    logLevelListPicker.setEditable(false);\n                }\n            }\n            var logLevel = logger.getLevel();\n            if (logLevel) {\n                if (logLevelListPicker) {\n                    logLevelListPicker.setValue([logLevel]);\n                }\n            }\n            if (logLevel === 'Trace') {\n                traceCategory.setVisible(true);\n                odataTrace.setVisible(true);\n            }\n\n            //Upon selecting a value in the List picker and clicking the back button \n            //will enable the onload page rule. This will set the selected value\n            //in the control\n            if (logLevelListPicker.getValue()[0]) {\n                var returnValue = logLevelListPicker.getValue()[0].ReturnValue;\n                if (returnValue) {\n                    logLevelListPicker.setValue([returnValue]);\n                    logger.setLevel(returnValue);\n                }\n            }\n        }\n    } catch (exception) {\n        // eslint-disable-next-line no-console\n        console.log(String(exception), 'Error User Logger could not be set');\n    }\n}","export default function Initialize(context) {\n\n    // Perform pre data initialization task\n\n    // Initialize all your Data sources\n    let _app_consumos_qa = context.executeAction('/appconsumos_qa_mb/Actions/app_consumos_qa/Service/InitializeOffline.action');\n    let ZBODEGA_AGO_SRV = context.executeAction('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/InitializeOffline.action');\n\n    //You can add more service initialize actions here\n\n    return Promise.all([_app_consumos_qa, ZBODEGA_AGO_SRV]).then(() => {\n        // After Initializing the DB connections\n\n        // Display successful initialization  message to the user\n        return context.executeAction({\n\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n            \"Properties\": {\n                \"Message\": \"Servicios de la aplicación inicializados\",\n                \"Animated\": true,\n                \"Duration\": 1,\n                \"IsIconHidden\": true,\n                \"NumberOfLines\": 1,\n                \"OnSuccess\": \"/appconsumos_qa_mb/Actions/app_consumos_qa/Service/UploadOffline.action\",\n            }\n        });\n    }).catch(() => {\n        return false;\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function CheckForSyncError(context) {\n    context.count('/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/.service', 'ErrorArchive', '').then(errorCount => {\n        if (errorCount > 0) {\n            return context.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/ErrorArchive/ErrorArchive_SyncFailure.action').then(function() {\n                return Promise.reject(false);\n            });\n        }\n    });\n}\n ","import get_Info_Usuario from '../get_Info_Usuario';\n/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function CheckForSyncError(context) {\n    context.count('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'ErrorArchive', '').then(errorCount => {\n        if (errorCount > 0) {\n            return context.getPageProxy().executeAction('/appconsumos_qa_mb/Actions/ErrorArchive/ErrorArchive_SyncFailure.action').then(function() {\n                return Promise.reject(false);\n            });\n        }else {\n            return get_Info_Usuario(context)\n        }\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function filter_Estado(context) {\n    var object = context.binding\n    alert(JSON.stringify(object))\n    return [\"estado eq Enviado\", \"estado eq Autorizado\"]\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function get_ConfirmacionTec(context) {\n    var object = context.binding\n    var confirmacion_tec = object.confirmacion_tec\n    if(!confirmacion_tec || confirmacion_tec === false){\n        return 'Entregado: No'\n    }\n\n    return 'Entregado: Si';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function get_Info_Usuario(context) {\n    let email = context.evaluateTargetPath('#Application/#AppData/UserId').toUpperCase();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    clientData.info_user = {}\n\n    //Syncroniza el servicio de datos del ERP\n    context.executeAction( \"/appconsumos_qa_mb/Actions/ZBODEGA_AGO_SRV/Service/UploadOffline.action\");\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=correo eq '${email}'`).then(async (results) => {\n        if (results && results.length > 0) {\n            clientData.info_user = results.getItem(0)\n        } \n    }).catch((error) => {\n        \n        alert(`Error ${error.message}`)\n    });\n\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function guid(context) {\n    function s4() {\n        return Math.floor((1 + Math.random()) * 0x10000).toString(16).substring(1);\n    }\n\n    function generarGUID() {\n        return s4() + s4() + '-' + s4() + '-' + s4() + '-' +\n               s4() + '-' + s4() + s4() + s4();\n    }\n\n    return generarGUID();\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_VisibleBtnAprobar(context) {\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    return estado === 'Aprobado' && info.rol === 'Autorizador';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function set_VisibleBtnConfirmar(context) {\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    return estado === 'Tramitado' && info.rol === 'Técnico';\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_VisibleBtnNetear(context) {\n    //Esta regla se usa en el boton de Salida en abastecimiento, en Netear en Ingenio, y en liquidar en Campo\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n\n    return estado === 'Autorizado' && info.rol === 'Auxiliar';\n    \n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function set_VisibleBtnRevisar(context) {\n    var object = context.binding\n    var estado = object.estado\n    let clientData = context.evaluateTargetPathForAPI('#Page:Main').getClientData();\n    let info = clientData.info_user;\n    /* \n      if (estado === 'Enviado' && info.rol === 'Auxiliar') {\n        return true;\n    } else{\n        return false;\n    }\n    */\n\n    return estado === 'Enviado' && info.rol === 'Auxiliar';\n\n}\n","// Imports\nvar ___CSS_LOADER_API_SOURCEMAP_IMPORT___ = require(\"../../../../../../../css-loader/dist/runtime/sourceMaps.js\");\nvar ___CSS_LOADER_API_IMPORT___ = require(\"../../../../../../../css-loader/dist/runtime/api.js\");\nvar ___CSS_LOADER_EXPORT___ = ___CSS_LOADER_API_IMPORT___(___CSS_LOADER_API_SOURCEMAP_IMPORT___);\n// Module\n___CSS_LOADER_EXPORT___.push([module.id, `/* The LESS stylesheet provides the ability to define styling styles that can be used to style the UI in the MDK app.\n\nExamples:\n\n@mdkYellow1: #ffbb33;\n@mdkRed1: #ff0000;\n\n//// By-Type style: All Pages in the application will now have a yellow background\nPage\n\n{ background-color: @mdkYellow1; }\n//// By-Name style: All Buttons with _Name == \"BlueButton\" will now have this style\n#BlueButton\n\n{ color: @mdkYellow1; background-color: #0000FF; }\n//// By-Class style: These style classes can be referenced from rules and set using ClientAPI setStyle function\n\n.MyButton\n\n{ color: @mdkYellow1; background-color: @mdkRed1; }\n*/\nActionBar {\n  color: white ;\n  background-color: #72BE44;\n}\n.HeaderAdmin {\n  color: white;\n  background-color: #72BE44;\n}\n.HeaderAdminTitle {\n  color: white;\n}\n.Button {\n  color: white;\n  background-color: #72BE44;\n}\n.ButtonText {\n  color: #72BE44;\n}\n.ButtonText2 {\n  color: #174087;\n}\n.Button2 {\n  color: white;\n  background-color: #174087;\n}\n.Button_Eliminar {\n  color: white;\n  background-color: #b22222;\n}\n.fondoForm {\n  background-color: gray;\n}\n`, \"\",{\"version\":3,\"sources\":[\"webpack://./build.definitions/appconsumos_qa_mb/Styles/Styles.css\"],\"names\":[],\"mappings\":\"AAAA;;;;;;;;;;;;;;;;;;;;CAoBC;AACD;EACE,aAAa;EACb,yBAAyB;AAC3B;AACA;EACE,YAAY;EACZ,yBAAyB;AAC3B;AACA;EACE,YAAY;AACd;AACA;EACE,YAAY;EACZ,yBAAyB;AAC3B;AACA;EACE,cAAc;AAChB;AACA;EACE,cAAc;AAChB;AACA;EACE,YAAY;EACZ,yB